  ('knowledge_batch_07', '.manus/db/db-query-error-1770368748592.json', 'page_settings', 'اتصل بنا', '4e8d25548c3f48be', 'assistant', 'page_settings', 'P1', 'staged', $kb07${"payload_kind": "legacy_sql_insert_row", "legacy_table": "page_settings", "source_file": ".manus/db/db-query-error-1770368748592.json", "row_index": 6, "columns": ["page_name", "title", "description", "meta_keywords", "og_image", "custom_css", "custom_js", "is_active"], "row": {"page_name": "contact", "title": "اتصل بنا", "description": "تواصل معنا للاستفسارات والاستشارات", "meta_keywords": "اتصل بنا، تواصل", "og_image": "", "custom_css": "", "custom_js": "", "is_active": "1"}}$kb07$::jsonb, 'legacy_sql_insert'),
  ('knowledge_batch_07', '.manus/db/db-query-error-1770368748592.json', 'page_settings', 'المدونة', '2fa44cd5b71ef732', 'assistant', 'page_settings', 'P1', 'staged', $kb07${"payload_kind": "legacy_sql_insert_row", "legacy_table": "page_settings", "source_file": ".manus/db/db-query-error-1770368748592.json", "row_index": 7, "columns": ["page_name", "title", "description", "meta_keywords", "og_image", "custom_css", "custom_js", "is_active"], "row": {"page_name": "blog", "title": "المدونة", "description": "آخر الأخبار والمقالات حول الأوقاف", "meta_keywords": "مدونة، أخبار، مقالات", "og_image": "", "custom_css": "", "custom_js": "", "is_active": "1"}}$kb07$::jsonb, 'legacy_sql_insert'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'العدل والإنصاف في معرفة أصول الفقه والاختلاف', '10e212cdb865ec8a', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 1, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "العدل والإنصاف في معرفة أصول الفقه والاختلاف", "author": "أبو يعقوب يوسف بن إبراهيم الوارجلاني", "category": "فقهي", "year": 570, "description": "كتاب أصولي فقهي مهم في المذهب الإباضي", "content": "يُعد كتاب 'العدل والإنصاف في معرفة أصول الفقه والاختلاف' من أهم المراجع الفقهية في المذهب الإباضي، ألفه الإمام أبو يعقوب يوسف بن إبراهيم الوارجلاني (توفي سنة 570هـ). يتناول الكتاب أصول الفقه الإسلامي ومناهج الاستدلال والاختلاف الفقهي بين المذاهب.\n\nيتميز الكتاب بمنهجه العلمي الدقيق في عرض المسائل الأصولية، حيث يعرض آراء المذاهب المختلفة بموضوعية وإنصاف، مع بيان الأدلة والحجج لكل رأي. يعتبر هذا الكتاب مرجعاً أساسياً لفهم منهج الاستدلال الفقهي وأصول الاجتهاد في الإسلام.\n\nيشمل الكتاب عدة أبواب رئيسية منها: مصادر التشريع الإسلامي (القرآن والسنة والإجماع والقياس)، قواعد الاستنباط الفقهي، مناهج التعامل مع النصوص الشرعية، أسباب الاختلاف الفقهي وآدابه، والقواعد الأصولية التي يُبنى عليها الفقه الإسلامي.\n\nيُعد هذا الكتاب مرجعاً مهماً لفهم الأوقاف الإسلامية من منظور أصولي، حيث يساعد في فهم الأسس الشرعية التي تُبنى عليها أحكام الوقف والشروط الواقفية وطرق إدارة الأوقاف وفق المقاصد الشرعية. كما يوضح كيفية التعامل مع الاختلافات الفقهية في مسائل الوقف بين المذاهب الإسلامية المختلفة.\n\nطُبع الكتاب عدة طبعات، منها طبعة وزارة التراث القومي والثقافة في سلطنة عمان عام 1404هـ/1984م، وهو يقع في عدة أجزاء تتجاوز 600 صفحة. يُعتبر من المراجع الأساسية في دراسة أصول الفقه الإسلامي، ويُدرس في الجامعات والمعاهد الشرعية في العالم الإسلامي.", "keywords": "أصول الفقه، الاختلاف الفقهي، المذهب الإباضي، الاستدلال الشرعي، القواعد الأصولية، الوارجلاني، مصادر التشريع"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'قانون العدل والإنصاف للقضاء على مشكلات الأوقاف', 'a14076a6290d142a', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 2, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "قانون العدل والإنصاف للقضاء على مشكلات الأوقاف", "author": "محمد قدري باشا", "category": "قانوني", "year": 1893, "description": "كتاب قانوني متخصص في حل مشكلات الأوقاف", "content": "كتاب 'قانون العدل والإنصاف للقضاء على مشكلات الأوقاف' من تأليف محمد قدري باشا (1821-1888م)، وهو أحد أبرز فقهاء القانون في العصر الحديث. يُعد هذا الكتاب من المراجع القانونية المهمة في مجال الأوقاف الإسلامية.\n\nيتناول الكتاب المشكلات القانونية والإدارية التي تواجه الأوقاف الإسلامية، ويقدم حلولاً قانونية مستمدة من الفقه الإسلامي والقانون الوضعي. يعالج الكتاب قضايا مثل: النزاعات على الأوقاف، شروط الواقفين، إدارة الأوقاف، استبدال الأوقاف، والإشراف القضائي على الأوقاف.\n\nألف محمد قدري باشا هذا الكتاب في سياق الإصلاحات القانونية التي شهدتها مصر في القرن التاسع عشر، حيث كان هناك حاجة لتنظيم قانوني حديث للأوقاف يحفظ حقوق الواقفين والمستحقين ويضمن حسن إدارة الأوقاف.\n\nيتميز الكتاب بجمعه بين الفقه الإسلامي التقليدي والقانون الحديث، مما يجعله مرجعاً مهماً للقضاة والمحامين والباحثين في مجال الأوقاف. يعرض الكتاب الأحكام الفقهية مع مراعاة الواقع العملي والحاجات المعاصرة.\n\nيُعتبر هذا الكتاب من المراجع الأساسية في فهم التطور القانوني لنظام الأوقاف في العالم العربي والإسلامي، وما زال يُستشهد به في المحاكم والدراسات القانونية المتعلقة بالأوقاف حتى اليوم.", "keywords": "قانون الأوقاف، مشكلات الأوقاف، محمد قدري باشا، القضاء، الإدارة الوقفية، النزاعات الوقفية"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'المغني - ابن قدامة المقدسي', '52c7ba54733ad312', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 3, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "المغني - ابن قدامة المقدسي", "author": "موفق الدين عبد الله بن أحمد بن قدامة المقدسي", "category": "فقهي", "year": 620, "description": "موسوعة فقهية شاملة في المذهب الحنبلي", "content": "كتاب 'المغني' للإمام موفق الدين ابن قدامة المقدسي (541-620هـ) من أهم الموسوعات الفقهية في المذهب الحنبلي والفقه الإسلامي عموماً. يُعد من أشمل كتب الفقه المقارن، حيث يعرض آراء المذاهب الأربعة مع الأدلة والترجيح.\n\nيتناول الكتاب جميع أبواب الفقه بما في ذلك باب الوقف، حيث يعرض أحكام الوقف بتفصيل دقيق: تعريف الوقف، شروطه، أركانه، أنواعه (الوقف الخيري والوقف الأهلي)، شروط الواقف، حقوق المستحقين، إدارة الوقف، استبدال الوقف، وإنهاء الوقف.\n\nيتميز المغني بمنهجه العلمي الرصين في عرض المسائل الفقهية، حيث يبدأ بذكر المسألة، ثم يعرض أقوال الفقهاء فيها، ثم يذكر الأدلة من الكتاب والسنة والإجماع والقياس، ثم يناقش الأدلة ويرجح ما يراه صواباً. هذا المنهج جعل الكتاب مرجعاً أساسياً للباحثين والمجتهدين.\n\nفي باب الوقف، يعرض ابن قدامة مسائل مهمة مثل: هل يشترط القبول في الوقف؟ هل يجوز الرجوع في الوقف؟ ما هي شروط صحة الوقف؟ كيف يُدار الوقف؟ متى يجوز استبدال الوقف؟ وغيرها من المسائل التي تهم القائمين على الأوقاف.\n\nطُبع الكتاب عدة طبعات محققة، ويقع في 15 مجلداً تقريباً. يُدرس في الجامعات الإسلامية ويُعتمد عليه في الفتوى والقضاء في كثير من البلدان الإسلامية.", "keywords": "المغني، ابن قدامة، الفقه الحنبلي، الفقه المقارن، أحكام الوقف، الموسوعة الفقهية"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الأم - الإمام الشافعي', '2476c4204c882c6a', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 4, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الأم - الإمام الشافعي", "author": "محمد بن إدريس الشافعي", "category": "فقهي", "year": 204, "description": "أصل المذهب الشافعي في الفقه", "content": "كتاب 'الأم' للإمام محمد بن إدريس الشافعي (150-204هـ) هو الكتاب الأصل في المذهب الشافعي، ويُعد من أهم المراجع الفقهية في التاريخ الإسلامي. يحتوي على آراء الإمام الشافعي الفقهية في جميع أبواب الفقه.\n\nيتناول الكتاب باب الوقف بتفصيل واضح، حيث يعرض الإمام الشافعي أحكام الوقف وشروطه وأنواعه. من أهم المسائل التي يعالجها: تعريف الوقف، حكم الوقف (هل هو لازم أم جائز)، شروط صحة الوقف، الوقف على النفس، الوقف على الذرية، الوقف الخيري، شروط الواقف، تغيير شروط الوقف، واستبدال الوقف.\n\nيتميز الكتاب بوضوح العبارة ودقة الاستدلال، حيث يعتمد الإمام الشافعي على النصوص الشرعية من القرآن والسنة، مع استخدام القياس والاستحسان في المسائل التي لا نص فيها. كما يناقش آراء الفقهاء السابقين ويبين وجه الصواب في المسائل الخلافية.\n\nمن أهم ما يميز موقف الإمام الشافعي في الوقف: اشتراط اللزوم في الوقف (أي أن الوقف لا يمكن الرجوع فيه بعد صحته)، وجواز الوقف على النفس ثم على الذرية ثم على الجهات الخيرية، واشتراط التأبيد في الوقف (أي أن يكون مؤبداً لا مؤقتاً).\n\nالكتاب مطبوع في عدة أجزاء (8-9 أجزاء حسب الطبعة)، ويُعتمد عليه في الفتوى والقضاء في البلدان التي تتبع المذهب الشافعي. كما يُدرس في الجامعات والمعاهد الشرعية كمرجع أساسي في الفقه الإسلامي.", "keywords": "الأم، الإمام الشافعي، المذهب الشافعي، الفقه الإسلامي، أحكام الوقف، الاستدلال الفقهي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'المبسوط - السرخسي', '7ba2e6be41eb445f', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 5, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "المبسوط - السرخسي", "author": "شمس الأئمة محمد بن أحمد السرخسي", "category": "فقهي", "year": 483, "description": "موسوعة فقهية ضخمة في المذهب الحنفي", "content": "كتاب 'المبسوط' للإمام شمس الأئمة السرخسي (توفي 483هـ) من أعظم الموسوعات الفقهية في المذهب الحنفي. ألفه السرخسي وهو في السجن، حيث كان يملي على تلاميذه من الذاكرة، مما يدل على عمق علمه وسعة اطلاعه.\n\nيقع الكتاب في 30 جزءاً، ويغطي جميع أبواب الفقه الإسلامي بتفصيل شامل. في باب الوقف، يعرض السرخسي أحكام الوقف في المذهب الحنفي مع مقارنتها بآراء المذاهب الأخرى. من أهم المسائل: تعريف الوقف عند الحنفية، شروط صحة الوقف، الفرق بين الوقف والصدقة، أنواع الوقف (الوقف الخيري والوقف الأهلي)، شروط الواقف، حقوق الموقوف عليهم، إدارة الوقف، واستبدال الوقف.\n\nمن أهم ما يميز المذهب الحنفي في الوقف: اشتراط القضاء أو التنفيذ في الوقف (أي أن الوقف لا يلزم إلا بالقضاء أو بالتنفيذ الفعلي)، وجواز الوقف على النفس عند أبي يوسف ومحمد (خلافاً لأبي حنيفة)، وجواز استبدال الوقف عند الحاجة.\n\nيتميز الكتاب بعمق التحليل الفقهي وكثرة الفروع والمسائل، مما يجعله مرجعاً لا غنى عنه للمتخصصين في الفقه الحنفي. كما يعرض السرخسي الأدلة الشرعية والقياسات الفقهية بطريقة واضحة ومنطقية.\n\nيُعتمد على المبسوط في الفتوى والقضاء في البلدان التي تتبع المذهب الحنفي، وهو من أهم المراجع في دراسة الفقه المقارن. طُبع الكتاب عدة طبعات محققة، ويُدرس في الجامعات الإسلامية حول العالم.", "keywords": "المبسوط، السرخسي، الفقه الحنفي، الموسوعة الفقهية، أحكام الوقف، الفقه المقارن"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'المدونة الكبرى - الإمام مالك', 'c2d43a0701e43264', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 6, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "المدونة الكبرى - الإمام مالك", "author": "الإمام مالك بن أنس (رواية سحنون عن ابن القاسم)", "category": "فقهي", "year": 240, "description": "أصل المذهب المالكي في الفقه", "content": "كتاب 'المدونة الكبرى' أو 'المدونة' هو الكتاب الأصل في المذهب المالكي، وهو من أهم المراجع الفقهية في التاريخ الإسلامي. المدونة هي رواية الإمام سحنون (توفي 240هـ) عن الإمام عبد الرحمن بن القاسم (توفي 191هـ) عن الإمام مالك بن أنس (93-179هـ).\n\nتتناول المدونة جميع أبواب الفقه الإسلامي، وتعرض آراء الإمام مالك وأصحابه في المسائل الفقهية. في باب الأحباس (الأوقاف)، تعرض المدونة أحكام الوقف في المذهب المالكي بتفصيل واضح.\n\nمن أهم ما يميز المذهب المالكي في الوقف: استخدام مصطلح 'الحبس' بدلاً من 'الوقف'، واشتراط التأبيد في الحبس (أي أن يكون مؤبداً لا مؤقتاً)، وجواز الحبس على النفس ثم على الذرية ثم على الجهات الخيرية، واشتراط اللزوم في الحبس (أي أن الحبس لا يمكن الرجوع فيه بعد صحته).\n\nتعالج المدونة مسائل مهمة في الأوقاف مثل: شروط صحة الحبس، حقوق المحبوس عليهم، إدارة الأحباس، استبدال الأحباس عند الحاجة، الحبس على المساجد والمدارس، والحبس على الذرية.\n\nيتميز أسلوب المدونة بالسؤال والجواب، حيث يسأل سحنون ابن القاسم عن المسائل الفقهية، ويجيب ابن القاسم بما سمعه من الإمام مالك أو بما يراه موافقاً لمذهبه. هذا الأسلوب يجعل الكتاب سهل القراءة وواضح الفهم.\n\nتقع المدونة في 16 جزءاً تقريباً، وهي مطبوعة ومتداولة. تُعتمد في الفتوى والقضاء في البلدان التي تتبع المذهب المالكي (شمال أفريقيا وغرب أفريقيا وبعض البلدان العربية). كما تُدرس في الجامعات الإسلامية كمرجع أساسي في الفقه المالكي.", "keywords": "المدونة، الإمام مالك، المذهب المالكي، الأحباس، الفقه الإسلامي، أحكام الوقف"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الموافقات في أصول الشريعة - الشاطبي', '0ba7fe0a96531bf9', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 7, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الموافقات في أصول الشريعة - الشاطبي", "author": "أبو إسحاق إبراهيم بن موسى الشاطبي", "category": "فقهي", "year": 790, "description": "كتاب مقاصد الشريعة والقواعد الأصولية", "content": "كتاب 'الموافقات' للإمام أبي إسحاق الشاطبي (توفي 790هـ) من أهم الكتب في علم مقاصد الشريعة وأصول الفقه. يُعد هذا الكتاب مرجعاً أساسياً لفهم المقاصد الشرعية والقواعد الكلية التي تحكم الاجتهاد الفقهي.\n\nيتناول الكتاب المقاصد الشرعية الخمسة (حفظ الدين، والنفس، والعقل، والنسل، والمال)، وكيفية تطبيقها في الاجتهاد الفقهي. كما يعرض القواعد الأصولية التي يُبنى عليها الفقه الإسلامي، مثل: قاعدة المصالح المرسلة، وقاعدة سد الذرائع، وقاعدة العرف، وقاعدة الاستحسان.\n\nفي مجال الأوقاف، يُعد كتاب الموافقات مرجعاً مهماً لفهم المقاصد الشرعية من الوقف، وهي: حفظ المال (من خلال استثمار الوقف)، وتحقيق المصلحة العامة (من خلال الوقف الخيري)، وحفظ حقوق الأجيال القادمة (من خلال التأبيد في الوقف).\n\nيساعد الكتاب في فهم كيفية التعامل مع المستجدات في الأوقاف، مثل: الأوقاف النقدية، والأوقاف الاستثمارية، والصكوك الوقفية، وغيرها من الصيغ الحديثة للوقف. كما يوضح كيفية الموازنة بين شروط الواقف والمصلحة العامة عند التعارض.\n\nيتميز الكتاب بعمق التحليل وشمولية الرؤية، حيث يربط بين الأحكام الجزئية والمقاصد الكلية للشريعة. يقع الكتاب في 4 أجزاء، وهو مطبوع ومتداول. يُدرس في الجامعات الإسلامية ويُعتمد عليه في الاجتهاد الفقهي المعاصر.\n\nيُعد الموافقات من أهم المراجع لمن يريد فهم الأسس الشرعية للأوقاف الإسلامية وكيفية تطويرها بما يتناسب مع العصر مع الحفاظ على المقاصد الشرعية.", "keywords": "الموافقات، الشاطبي، مقاصد الشريعة، أصول الفقه، المصالح المرسلة، الاجتهاد الفقهي، الأوقاف"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'إعلام الموقعين عن رب العالمين - ابن القيم', '7eaa91d1547fd3c5', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 8, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "إعلام الموقعين عن رب العالمين - ابن القيم", "author": "شمس الدين محمد بن أبي بكر ابن قيم الجوزية", "category": "فقهي", "year": 751, "description": "كتاب في أصول الفقه والفتوى والقضاء", "content": "كتاب 'إعلام الموقعين عن رب العالمين' للإمام ابن قيم الجوزية (691-751هـ) من أهم الكتب في أصول الفقه والفتوى والقضاء. يُعد مرجعاً أساسياً لفهم منهج الاجتهاد والفتوى في الإسلام.\n\nيتناول الكتاب قواعد الفتوى وآدابها، ومناهج الاستدلال الفقهي، وأسباب الاختلاف بين الفقهاء، وكيفية الترجيح بين الأقوال المختلفة. كما يعرض قواعد فقهية مهمة مثل: تغير الفتوى بتغير الزمان والمكان والعرف، واعتبار المآلات في الأحكام، والموازنة بين المصالح والمفاسد.\n\nفي مجال الأوقاف، يُعد الكتاب مرجعاً مهماً لفهم كيفية التعامل مع المستجدات في الأوقاف، وكيفية الاجتهاد في المسائل التي لم ينص عليها الفقهاء السابقون. كما يوضح كيفية الموازنة بين شروط الواقف والمصلحة العامة، وكيفية تطبيق قاعدة 'تغير الفتوى بتغير الزمان' على مسائل الأوقاف.\n\nمن أهم ما يعالجه الكتاب في مجال الأوقاف: مسألة استبدال الوقف عند الحاجة، ومسألة تغيير شروط الواقف إذا أصبحت غير قابلة للتطبيق، ومسألة الوقف على جهات لم تعد موجودة، وكيفية التصرف في ريع الوقف بما يحقق مقصد الواقف.\n\nيتميز الكتاب بأسلوبه الواضح وحججه القوية، حيث يعتمد ابن القيم على النصوص الشرعية والقواعد الأصولية والمقاصد الشرعية في بناء آرائه. كما يناقش آراء الفقهاء السابقين بموضوعية ويبين وجه الصواب في المسائل الخلافية.\n\nيقع الكتاب في 4 أجزاء، وهو مطبوع ومتداول. يُدرس في الجامعات الإسلامية ويُعتمد عليه في الفتوى والاجتهاد الفقهي المعاصر. يُعد من أهم المراجع لمن يريد فهم منهج التجديد الفقهي في الأوقاف الإسلامية.", "keywords": "إعلام الموقعين، ابن القيم، أصول الفقه، الفتوى، الاجتهاد، تغير الأحكام، المقاصد الشرعية، الأوقاف"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الأشباه والنظائر - السيوطي', '95904d2f7a824365', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 9, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الأشباه والنظائر - السيوطي", "author": "جلال الدين عبد الرحمن السيوطي", "category": "فقهي", "year": 911, "description": "كتاب القواعد الفقهية الكلية", "content": "كتاب 'الأشباه والنظائر' للإمام جلال الدين السيوطي (849-911هـ) من أهم الكتب في القواعد الفقهية الكلية. يجمع الكتاب القواعد الفقهية التي تنطبق على مسائل متعددة في أبواب الفقه المختلفة.\n\nيتناول الكتاب القواعد الفقهية الخمس الكبرى: (1) الأمور بمقاصدها، (2) اليقين لا يزول بالشك، (3) المشقة تجلب التيسير، (4) الضرر يزال، (5) العادة محكمة. كما يعرض قواعد فرعية كثيرة تتعلق بجميع أبواب الفقه.\n\nفي مجال الأوقاف، تُطبق هذه القواعد على مسائل عديدة، مثل:\n- قاعدة 'الأمور بمقاصدها': تُطبق في فهم شروط الواقف وتفسيرها بما يحقق مقصده.\n- قاعدة 'اليقين لا يزول بالشك': تُطبق في النزاعات حول الوقف، حيث لا يُحكم بإنهاء الوقف بمجرد الشك.\n- قاعدة 'المشقة تجلب التيسير': تُطبق في استبدال الوقف عند المشقة أو عدم تحقق المنفعة.\n- قاعدة 'الضرر يزال': تُطبق في إزالة الضرر عن الوقف أو عن المستحقين.\n- قاعدة 'العادة محكمة': تُطبق في تفسير شروط الواقف وفق العرف السائد في زمانه.\n\nيتميز الكتاب بوضوح العرض وكثرة الأمثلة التطبيقية، مما يجعله سهل الفهم ومفيداً للمتخصصين وغير المتخصصين. يقع الكتاب في مجلد واحد، وهو مطبوع ومتداول.\n\nيُعتمد على الأشباه والنظائر في الفتوى والقضاء، حيث تساعد القواعد الفقهية في حل المسائل المستجدة التي لم ينص عليها الفقهاء السابقون. كما يُدرس الكتاب في الجامعات الإسلامية كمقرر أساسي في القواعد الفقهية.\n\nيُعد الكتاب مرجعاً لا غنى عنه لمن يعمل في مجال الأوقاف، حيث يساعد في فهم الأحكام الفقهية وتطبيقها على الحالات المختلفة بطريقة منهجية ومنضبطة.", "keywords": "الأشباه والنظائر، السيوطي، القواعد الفقهية، الفقه الإسلامي، الأمور بمقاصدها، العادة محكمة، الأوقاف"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'المجلة العدلية (مجلة الأحكام العدلية)', '08e371fcd654a46d', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 10, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "المجلة العدلية (مجلة الأحكام العدلية)", "author": "لجنة من فقهاء الدولة العثمانية", "category": "قانوني", "year": 1876, "description": "أول تقنين للفقه الإسلامي في العصر الحديث", "content": "المجلة العدلية أو 'مجلة الأحكام العدلية' هي أول تقنين للفقه الإسلامي (المذهب الحنفي) في العصر الحديث. صدرت في الدولة العثمانية عام 1293هـ/1876م، وتتكون من 1851 مادة قانونية موزعة على 16 كتاباً.\n\nتغطي المجلة العدلية المعاملات المدنية والتجارية في الفقه الإسلامي، وتشمل: البيوع، الإجارة، الكفالة، الحوالة، الرهن، الأمانات، الهبة، الغصب، الإتلاف، الحجر، الإكراه، الشفعة، الشركة، الوكالة، الصلح، الإقرار، والدعوى والبينات.\n\nفي مجال الأوقاف، تتضمن المجلة العدلية أحكاماً مهمة في عدة كتب، خاصة في كتاب الإجارة (حيث يُعامل استئجار الوقف)، وكتاب الهبة (حيث يُقارن الوقف بالهبة)، وكتاب الغصب (حيث تُعالج مسألة الاعتداء على الأوقاف).\n\nتبدأ المجلة بـ 99 قاعدة فقهية كلية، تُعد من أهم القواعد في الفقه الإسلامي، مثل: 'الأمور بمقاصدها'، 'اليقين لا يزول بالشك'، 'المشقة تجلب التيسير'، 'الضرر يزال'، 'العادة محكمة'، 'القديم يترك على قدمه'، 'الضرورات تبيح المحظورات'، وغيرها.\n\nتُطبق هذه القواعد على مسائل الأوقاف، مثل: تفسير شروط الواقف وفق مقصده، والحفاظ على الوقف القديم دون تغيير إلا للضرورة، واستبدال الوقف عند الضرورة، وإزالة الضرر عن الوقف أو المستحقين.\n\nطُبقت المجلة العدلية في الدولة العثمانية وفي البلدان التي كانت تحت حكمها، واستمر العمل بها في بعض البلدان العربية حتى منتصف القرن العشرين. ما زالت المجلة مرجعاً مهماً في القانون المدني الإسلامي، وتُدرس في كليات الحقوق والشريعة.\n\nتُعد المجلة العدلية نموذجاً ناجحاً لتقنين الفقه الإسلامي بطريقة حديثة، وقد ألهمت محاولات تقنين لاحقة في العالم الإسلامي.", "keywords": "المجلة العدلية، التقنين، الفقه الحنفي، القانون المدني الإسلامي، القواعد الفقهية، الدولة العثمانية، الأوقاف"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الفقه الإسلامي وأدلته - وهبة الزحيلي', '58a12fdb792d8c6f', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 11, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الفقه الإسلامي وأدلته - وهبة الزحيلي", "author": "وهبة مصطفى الزحيلي", "category": "فقهي", "year": 1997, "description": "موسوعة فقهية معاصرة شاملة", "content": "كتاب 'الفقه الإسلامي وأدلته' للدكتور وهبة الزحيلي (1932-2015م) من أشمل الموسوعات الفقهية المعاصرة. يقع في 11 مجلداً، ويغطي جميع أبواب الفقه الإسلامي مع عرض آراء المذاهب الأربعة والأدلة والترجيح.\n\nيتميز الكتاب بمنهجه الشامل، حيث يعرض لكل مسألة: تعريفها، حكمها في المذاهب الأربعة، الأدلة من الكتاب والسنة والإجماع والقياس، مناقشة الأدلة، الترجيح، والتطبيقات المعاصرة.\n\nفي باب الوقف، يعرض الدكتور الزحيلي أحكام الوقف بتفصيل شامل في عدة فصول، تشمل: تعريف الوقف وحكمه ومشروعيته، أركان الوقف وشروطه، أنواع الوقف (الخيري والأهلي والمشترك)، شروط الواقف وحقوقه، حقوق الموقوف عليهم، إدارة الوقف ونظارته، استبدال الوقف وشروطه، إنهاء الوقف، والأحكام المعاصرة للوقف.\n\nمن أهم ما يميز الكتاب في مجال الأوقاف: عرضه للصيغ الحديثة للوقف مثل الوقف النقدي والوقف الاستثماري والصكوك الوقفية، ومعالجته للمشكلات المعاصرة في الأوقاف مثل الأوقاف المتعطلة والأوقاف المهجورة وكيفية إحيائها.\n\nيعتمد الدكتور الزحيلي في ترجيحاته على الأدلة الشرعية والمقاصد الشرعية والمصلحة العامة، مع مراعاة الواقع المعاصر. كما يستشهد بالقوانين المعاصرة للأوقاف في البلدان الإسلامية.\n\nيُعد الكتاب مرجعاً أساسياً للباحثين والمفتين والقضاة والعاملين في مجال الأوقاف. يُدرس في الجامعات الإسلامية حول العالم، وتُرجم إلى عدة لغات. يتميز بوضوح العبارة وسهولة الفهم مع العمق العلمي.", "keywords": "الفقه الإسلامي وأدلته، وهبة الزحيلي، الموسوعة الفقهية، الفقه المقارن، أحكام الوقف، الفقه المعاصر"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'أحكام الوقف في الشريعة الإسلامية - محمد عبيد الكبيسي', '492c28f3abc0d654', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 12, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "أحكام الوقف في الشريعة الإسلامية - محمد عبيد الكبيسي", "author": "محمد عبيد الكبيسي", "category": "فقهي", "year": 1977, "description": "دراسة فقهية متخصصة في الوقف", "content": "كتاب 'أحكام الوقف في الشريعة الإسلامية' للدكتور محمد عبيد الكبيسي من أهم الدراسات الفقهية المتخصصة في الوقف الإسلامي. نُشر الكتاب عام 1977م، ويُعد مرجعاً أساسياً في مجال الأوقاف.\n\nيتناول الكتاب جميع جوانب الوقف الإسلامي بتفصيل شامل، ويقع في جزأين كبيرين. يعرض الكتاب أحكام الوقف في المذاهب الأربعة مع المقارنة والترجيح، كما يعرض التطبيقات العملية للوقف عبر التاريخ الإسلامي.\n\nيتضمن الكتاب الأبواب التالية: تعريف الوقف ومشروعيته وحكمه، أركان الوقف (الواقف، الموقوف، الموقوف عليه، الصيغة)، شروط الوقف، أنواع الوقف (الخيري والأهلي والمشترك)، آثار الوقف، إدارة الوقف ونظارته، استبدال الوقف، إنهاء الوقف، والقضايا المعاصرة في الأوقاف.\n\nمن أهم ما يميز الكتاب: عمق التحليل الفقهي، وكثرة الأمثلة التطبيقية من التاريخ الإسلامي، ومعالجة المشكلات العملية التي تواجه الأوقاف، واقتراح حلول فقهية لها.\n\nيعالج الكتاب قضايا مهمة مثل: الوقف على النفس، الوقف المؤقت، الوقف على الجهات غير المحددة، الوقف على غير المسلمين، الوقف على الذرية المنقرضة، استبدال الوقف عند الخراب أو قلة الريع، والوقف النقدي.\n\nيُعتمد على الكتاب في الفتوى والقضاء والبحث العلمي في مجال الأوقاف. يُدرس في كليات الشريعة والقانون في الجامعات العربية والإسلامية. يتميز بأسلوبه العلمي الدقيق وعرضه المنهجي للمسائل.\n\nيُعد الكتاب مرجعاً لا غنى عنه لكل من يعمل في مجال الأوقاف الإسلامية، سواء كان قاضياً أو مفتياً أو إدارياً أو باحثاً.", "keywords": "أحكام الوقف، الكبيسي، الفقه الإسلامي، الوقف الخيري، الوقف الأهلي، إدارة الأوقاف، استبدال الوقف"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الوقف الإسلامي: تطوره، إدارته، تنميته - منذر قحف', '2b38ab7dfbac88da', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 13, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الوقف الإسلامي: تطوره، إدارته، تنميته - منذر قحف", "author": "منذر قحف", "category": "إداري", "year": 2000, "description": "دراسة اقتصادية وإدارية للوقف الإسلامي", "content": "كتاب 'الوقف الإسلامي: تطوره، إدارته، تنميته' للدكتور منذر قحف من أهم الدراسات الاقتصادية والإدارية المعاصرة في مجال الأوقاف الإسلامية. يجمع الكتاب بين الفقه الإسلامي والاقتصاد والإدارة.\n\nيتناول الكتاب تاريخ الوقف الإسلامي وتطوره عبر العصور، ودوره الاقتصادي والاجتماعي في المجتمعات الإسلامية. كما يعرض أساليب إدارة الأوقاف التقليدية والحديثة، وطرق تنمية الأوقاف واستثمارها.\n\nمن أهم موضوعات الكتاب: الوقف النقدي (وقف الأموال السائلة)، الصكوك الوقفية (أدوات مالية إسلامية للوقف)، الوقف الاستثماري (استثمار أموال الوقف في مشاريع مربحة)، إدارة الأوقاف بطريقة احترافية، والحوكمة في الأوقاف.\n\nيقدم الكتاب نماذج ناجحة من الأوقاف الإسلامية المعاصرة في مختلف البلدان، ويحلل أسباب نجاحها. كما يعرض التحديات التي تواجه الأوقاف الإسلامية في العصر الحديث، مثل: ضعف الإدارة، قلة الاستثمار، البيروقراطية، والفساد.\n\nيقترح الكتاب حلولاً عملية لتطوير الأوقاف الإسلامية، منها: تطبيق مبادئ الإدارة الحديثة، استخدام التكنولوجيا في إدارة الأوقاف، تطوير صيغ استثمارية جديدة متوافقة مع الشريعة، تفعيل دور الوقف في التنمية الاقتصادية والاجتماعية، وتعزيز الشفافية والمساءلة في إدارة الأوقاف.\n\nيُعد الكتاب مرجعاً مهماً للمسؤولين عن إدارة الأوقاف والباحثين في الاقتصاد الإسلامي والتنمية. يتميز بجمعه بين النظرية والتطبيق، وبين الفقه والاقتصاد، وبين التراث والمعاصرة.\n\nصدر الكتاب عن البنك الإسلامي للتنمية، ويُعتمد عليه في تدريب العاملين في مؤسسات الأوقاف الإسلامية حول العالم.", "keywords": "الوقف الإسلامي، منذر قحف، الاقتصاد الإسلامي، إدارة الأوقاف، الوقف النقدي، الصكوك الوقفية، الاستثمار الوقفي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'قانون الأوقاف الفلسطيني رقم 2 لسنة 2014', 'f12fb2452f131d86', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 14, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "قانون الأوقاف الفلسطيني رقم 2 لسنة 2014", "author": "السلطة الوطنية الفلسطينية", "category": "قانوني", "year": 2014, "description": "القانون المنظم للأوقاف في فلسطين", "content": "قانون الأوقاف الفلسطيني رقم 2 لسنة 2014 هو القانون المنظم للأوقاف في فلسطين، صدر عن السلطة الوطنية الفلسطينية. يُعد هذا القانون من أهم التشريعات القانونية المتعلقة بالأوقاف في فلسطين.\n\nيتكون القانون من 52 مادة موزعة على عدة فصول، تشمل: التعاريف والأحكام العامة، أنواع الأوقاف، شروط الوقف وأركانه، إدارة الأوقاف، صلاحيات وزارة الأوقاف، نظارة الأوقاف، استثمار الأوقاف، استبدال الأوقاف، حماية الأوقاف، والعقوبات.\n\nمن أهم ما ينظمه القانون:\n1. تعريف الوقف: 'حبس العين على حكم ملك الله تعالى والتصدق بالمنفعة على جهة بر وخير'.\n2. أنواع الوقف: الوقف الخيري (على جهات البر)، والوقف الذري (على الذرية ثم على جهة خيرية).\n3. شروط الوقف: أن يكون الواقف أهلاً للتبرع، وأن يكون الموقوف مالاً متقوماً، وأن يكون الوقف مؤبداً.\n4. إدارة الأوقاف: تتولى وزارة الأوقاف والشؤون الدينية إدارة الأوقاف الخيرية، بينما يتولى الناظر إدارة الوقف الذري.\n5. استثمار الأوقاف: يجوز استثمار أموال الأوقاف بطرق مشروعة لتنمية الوقف وزيادة ريعه.\n6. استبدال الوقف: يجوز استبدال الوقف بإذن المحكمة الشرعية عند توفر شروط معينة (خراب الوقف، قلة منفعته، وجود مصلحة راجحة).\n7. حماية الأوقاف: يُحظر الاعتداء على الأوقاف أو التصرف فيها بما يخالف شروط الواقف أو القانون، مع فرض عقوبات على المخالفين.\n\nيُطبق هذا القانون في الأراضي الفلسطينية الخاضعة لسيطرة السلطة الوطنية الفلسطينية. يُعتمد عليه في المحاكم الشرعية والمحاكم النظامية في القضايا المتعلقة بالأوقاف.\n\nيُعد القانون خطوة مهمة نحو تنظيم الأوقاف في فلسطين وحمايتها من الضياع والاعتداء، خاصة في ظل الظروف السياسية الصعبة التي تمر بها فلسطين.", "keywords": "قانون الأوقاف الفلسطيني، السلطة الفلسطينية، التشريع الفلسطيني، وزارة الأوقاف، حماية الأوقاف، فلسطين"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الأوقاف الإسلامية في القدس الشريف - كامل جميل العسلي', '7c01d7b1089db8c9', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 15, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الأوقاف الإسلامية في القدس الشريف - كامل جميل العسلي", "author": "كامل جميل العسلي", "category": "تاريخي", "year": 1981, "description": "دراسة تاريخية عن أوقاف القدس", "content": "كتاب 'الأوقاف الإسلامية في القدس الشريف' للمؤرخ الدكتور كامل جميل العسلي (1919-2015م) من أهم الدراسات التاريخية عن الأوقاف الإسلامية في القدس. نُشر الكتاب عام 1981م.\n\nيتناول الكتاب تاريخ الأوقاف الإسلامية في القدس منذ الفتح الإسلامي حتى العصر الحديث، مع التركيز على العصر المملوكي والعثماني. يعرض الكتاب أنواع الأوقاف في القدس: أوقاف المساجد، أوقاف المدارس، أوقاف الزوايا والخوانق، أوقاف التكايا، أوقاف الأسبلة، وأوقاف البيمارستانات (المستشفيات).\n\nيوثق الكتاب مئات الأوقاف في القدس بالاعتماد على وثائق المحاكم الشرعية وسجلات الأوقاف العثمانية. يعرض لكل وقف: اسم الواقف، تاريخ الوقف، الموقوف (عقارات، أراضي، دكاكين)، الموقوف عليه (مسجد، مدرسة، فقراء)، شروط الواقف، والناظر على الوقف.\n\nمن أهم الأوقاف التي يوثقها الكتاب: وقف صلاح الدين الأيوبي، وقف السلطان الناصر محمد بن قلاوون، وقف السلطان الأشرف برسباي، وقف خاصكي سلطان (زوجة السلطان سليمان القانوني)، وقف السلطان سليم الأول، وغيرها من الأوقاف الكبرى.\n\nيبرز الكتاب الدور الحضاري للأوقاف في القدس، حيث ساهمت في: بناء وصيانة المساجد والمدارس، توفير التعليم المجاني، إطعام الفقراء والمساكين، توفير الماء للسكان والحجاج، رعاية المرضى، واستضافة الزوار والحجاج.\n\nيعالج الكتاب أيضاً التحديات التي واجهت الأوقاف في القدس، خاصة في العصر الحديث، مثل: الاحتلال البريطاني وسياساته تجاه الأوقاف، الاحتلال الإسرائيلي ومحاولاته للسيطرة على الأوقاف، والنزاعات القانونية حول ملكية الأوقاف.\n\nيُعد الكتاب مرجعاً أساسياً لفهم تاريخ القدس الإسلامي والدور الحضاري للأوقاف. يُستشهد به في الدراسات التاريخية والقانونية المتعلقة بالقدس والأوقاف الإسلامية فيها.", "keywords": "أوقاف القدس، كامل العسلي، التاريخ الإسلامي، القدس الشريف، الأوقاف المملوكية، الأوقاف العثمانية، فلسطين"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الأوقاف في فلسطين: دراسة تاريخية وثائقية', 'c59a68b91406df14', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 16, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الأوقاف في فلسطين: دراسة تاريخية وثائقية", "author": "محمد عدنان البخيت وآخرون", "category": "تاريخي", "year": 2000, "description": "دراسة شاملة عن تاريخ الأوقاف في فلسطين", "content": "كتاب 'الأوقاف في فلسطين: دراسة تاريخية وثائقية' من تأليف مجموعة من الباحثين بإشراف الدكتور محمد عدنان البخيت. يُعد من أشمل الدراسات عن تاريخ الأوقاف في فلسطين.\n\nيغطي الكتاب تاريخ الأوقاف في فلسطين منذ الفتح الإسلامي (636م) حتى نهاية الحكم العثماني (1918م)، مع التركيز على العصرين المملوكي (1260-1516م) والعثماني (1516-1918م). يعتمد الكتاب على وثائق أرشيفية من سجلات المحاكم الشرعية والأرشيف العثماني.\n\nيتناول الكتاب عدة موضوعات رئيسية:\n1. أنواع الأوقاف في فلسطين: الأوقاف الخيرية (على المساجد والمدارس والمستشفيات)، والأوقاف الذرية (على الذرية ثم على جهة خيرية).\n2. الواقفون في فلسطين: السلاطين والأمراء، العلماء والقضاة، التجار والأعيان، وعامة الناس.\n3. الموقوفات: العقارات (بيوت، دكاكين، خانات، حمامات)، الأراضي الزراعية، البساتين، والطواحين.\n4. الموقوف عليهم: المساجد، المدارس، الزوايا، التكايا، الفقراء والمساكين، الأيتام، وطلاب العلم.\n5. إدارة الأوقاف: نظام النظارة، دور القاضي الشرعي، ودور ديوان الأوقاف العثماني.\n6. ريع الأوقاف: مصادره (إيجارات، مزارعة، مقاطعة)، وأوجه صرفه (صيانة، رواتب، خدمات).\n\nيوثق الكتاب مئات الأوقاف في مدن فلسطين الرئيسية: القدس، الخليل، نابلس، غزة، يافا، حيفا، عكا، صفد، والرملة. يعرض لكل وقف معلومات تفصيلية مستقاة من الوثائق الأصلية.\n\nيبرز الكتاب الدور الحضاري والاجتماعي للأوقاف في فلسطين، حيث ساهمت في: التعليم، الرعاية الصحية، الرعاية الاجتماعية، توفير المياه، استضافة الحجاج والزوار، والتنمية الاقتصادية.\n\nيُعد الكتاب مرجعاً أساسياً للباحثين في تاريخ فلسطين والأوقاف الإسلامية. يتميز بالتوثيق الدقيق والاعتماد على المصادر الأولية.", "keywords": "أوقاف فلسطين، التاريخ الإسلامي، الوثائق العثمانية، المحاكم الشرعية، محمد البخيت، فلسطين"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'نظام الأوقاف في التطبيق المعاصر - عبد الله بن ناصر السدحان', 'acb9fa760957d578', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 17, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "نظام الأوقاف في التطبيق المعاصر - عبد الله بن ناصر السدحان", "author": "عبد الله بن ناصر السدحان", "category": "إداري", "year": 2007, "description": "دراسة معاصرة لإدارة الأوقاف", "content": "كتاب 'نظام الأوقاف في التطبيق المعاصر' للدكتور عبد الله بن ناصر السدحان من أهم الدراسات المعاصرة في إدارة الأوقاف الإسلامية. نُشر الكتاب عام 2007م، ويجمع بين الفقه والإدارة والقانون.\n\nيتناول الكتاب النظام القانوني والإداري للأوقاف في العصر الحديث، مع التركيز على التجارب المعاصرة في البلدان الإسلامية. يعرض الكتاب نماذج من أنظمة الأوقاف في: السعودية، الكويت، قطر، الأردن، مصر، تركيا، وماليزيا.\n\nمن أهم موضوعات الكتاب:\n1. الإطار القانوني للأوقاف: القوانين والأنظمة المنظمة للأوقاف في البلدان الإسلامية.\n2. الهيكل التنظيمي لإدارة الأوقاف: الوزارات، الهيئات، الإدارات، والمؤسسات الوقفية.\n3. صلاحيات إدارة الأوقاف: الإشراف، التسجيل، الاستثمار، الصرف، والرقابة.\n4. نظام النظارة على الأوقاف: شروط الناظر، صلاحياته، مسؤولياته، ومحاسبته.\n5. استثمار الأوقاف: الصيغ الاستثمارية المعاصرة (المرابحة، المشاركة، المضاربة، الإجارة، الاستصناع).\n6. الصكوك الوقفية: تعريفها، أنواعها، ضوابطها الشرعية، وتطبيقاتها.\n7. الوقف النقدي: حكمه، ضوابطه، وطرق استثماره.\n8. استبدال الأوقاف: شروطه، إجراءاته، والجهات المختصة.\n9. الحوكمة في الأوقاف: الشفافية، المساءلة، الإفصاح، والرقابة.\n10. التحديات المعاصرة للأوقاف: ضعف الإدارة، قلة الاستثمار، البيروقراطية، الفساد، والاعتداءات.\n\nيقدم الكتاب توصيات عملية لتطوير إدارة الأوقاف، منها: تحديث الأنظمة والقوانين، تطبيق مبادئ الإدارة الحديثة، تدريب العاملين، استخدام التكنولوجيا، تطوير صيغ استثمارية جديدة، وتعزيز الشفافية والمساءلة.\n\nيُعد الكتاب مرجعاً مهماً للمسؤولين عن إدارة الأوقاف والباحثين في مجال الأوقاف الإسلامية. يتميز بالجمع بين النظرية والتطبيق، وبين الفقه والقانون والإدارة.", "keywords": "نظام الأوقاف، السدحان، إدارة الأوقاف، الصكوك الوقفية، الوقف النقدي، الحوكمة، الاستثمار الوقفي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الوقف الإسلامي بين النظرية والتطبيق - حسن عبد الله الأمين', '4ff48defb42a8cbb', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 18, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الوقف الإسلامي بين النظرية والتطبيق - حسن عبد الله الأمين", "author": "حسن عبد الله الأمين", "category": "فقهي", "year": 2009, "description": "دراسة شاملة تجمع بين الفقه والتطبيق", "content": "كتاب 'الوقف الإسلامي بين النظرية والتطبيق' للدكتور حسن عبد الله الأمين من الدراسات الشاملة التي تجمع بين الجانب الفقهي والجانب العملي للوقف الإسلامي. نُشر الكتاب عام 2009م.\n\nيتكون الكتاب من قسمين رئيسيين:\nالقسم الأول: النظرية الفقهية للوقف، ويشمل: تعريف الوقف، مشروعيته، حكمه، أركانه، شروطه، أنواعه، آثاره، وأحكامه في المذاهب الأربعة.\nالقسم الثاني: التطبيق العملي للوقف، ويشمل: تاريخ الأوقاف في الإسلام، نماذج من الأوقاف التاريخية، إدارة الأوقاف، استثمار الأوقاف، التحديات المعاصرة، والحلول المقترحة.\n\nمن أهم ما يميز الكتاب:\n1. الجمع بين الفقه والتاريخ والإدارة والاقتصاد في دراسة الوقف.\n2. عرض نماذج تطبيقية ناجحة من الأوقاف الإسلامية عبر التاريخ.\n3. تحليل التحديات المعاصرة التي تواجه الأوقاف واقتراح حلول عملية لها.\n4. التركيز على دور الوقف في التنمية الاقتصادية والاجتماعية.\n5. معالجة الصيغ الحديثة للوقف مثل الوقف النقدي والصكوك الوقفية.\n\nيعرض الكتاب نماذج من الأوقاف التاريخية الناجحة، مثل: وقف عثمان بن عفان على بئر رومة، وقف عمر بن الخطاب على أرضه في خيبر، أوقاف صلاح الدين الأيوبي، أوقاف السلطان محمد الفاتح، وأوقاف السلطان سليمان القانوني.\n\nيحلل الكتاب أسباب نجاح هذه الأوقاف، ويستخلص دروساً يمكن تطبيقها في الأوقاف المعاصرة، مثل: حسن اختيار الموقوف، جودة الإدارة، الاستثمار الحكيم، الشفافية، والمحاسبة.\n\nيعالج الكتاب التحديات المعاصرة للأوقاف، مثل: ضعف الإدارة، قلة الموارد، البيروقراطية، الفساد، الاعتداءات على الأوقاف، وضعف الوعي بأهمية الوقف. ويقترح حلولاً عملية لكل تحدٍ.\n\nيُعد الكتاب مرجعاً مفيداً للباحثين والعاملين في مجال الأوقاف والمهتمين بالتنمية الاقتصادية والاجتماعية في العالم الإسلامي.", "keywords": "الوقف الإسلامي، حسن الأمين، النظرية والتطبيق، إدارة الأوقاف، التنمية، التاريخ الإسلامي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'دور الوقف في المجتمع الإسلامي المعاصر - يوسف القرضاوي', '0d9a948330641eab', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 19, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "دور الوقف في المجتمع الإسلامي المعاصر - يوسف القرضاوي", "author": "يوسف القرضاوي", "category": "فقهي", "year": 2008, "description": "رؤية معاصرة لدور الوقف في التنمية", "content": "كتاب 'دور الوقف في المجتمع الإسلامي المعاصر' للشيخ الدكتور يوسف القرضاوي من الدراسات المهمة التي تعرض رؤية معاصرة لدور الوقف في التنمية الشاملة. نُشر الكتاب عام 2008م.\n\nيتناول الكتاب الوقف من منظور شامل، حيث يعرض: الأساس الشرعي للوقف، الدور التاريخي للوقف في الحضارة الإسلامية، الدور المعاصر للوقف في التنمية، والرؤية المستقبلية للوقف.\n\nمن أهم أفكار الكتاب:\n1. الوقف أداة للتكافل الاجتماعي: يساهم الوقف في سد حاجات الفقراء والمحتاجين دون إذلال أو منّة.\n2. الوقف أداة للتنمية الاقتصادية: يوفر الوقف موارد مستدامة للمشاريع التنموية.\n3. الوقف أداة للتنمية التعليمية: يساهم الوقف في بناء المدارس والجامعات وتوفير المنح الدراسية.\n4. الوقف أداة للتنمية الصحية: يساهم الوقف في بناء المستشفيات والمراكز الصحية.\n5. الوقف أداة لحفظ التراث: يساهم الوقف في صيانة المساجد والمعالم التاريخية.\n\nيدعو الشيخ القرضاوي إلى إحياء الوقف في المجتمعات الإسلامية المعاصرة، ويقترح صيغاً جديدة للوقف تتناسب مع العصر، مثل:\n- الوقف النقدي: وقف الأموال السائلة واستثمارها في مشاريع مربحة.\n- الوقف الاستثماري: إنشاء شركات وقفية تدير مشاريع تجارية وصناعية.\n- الصكوك الوقفية: إصدار أدوات مالية إسلامية لجمع التبرعات الوقفية.\n- الوقف الإلكتروني: استخدام التكنولوجيا لتسهيل الوقف وإدارته.\n- الوقف المهني: وقف الخبرات والمهارات (مثل وقف ساعات من وقت الطبيب أو المهندس).\n\nيعالج الكتاب التحديات التي تواجه الوقف المعاصر، مثل: ضعف الوعي بأهمية الوقف، ضعف الإدارة، قلة الاستثمار، والبيروقراطية. ويقترح حلولاً عملية لهذه التحديات.\n\nيُعد الكتاب مرجعاً مهماً للدعاة والمفكرين والمسؤولين عن الأوقاف. يتميز بأسلوبه الواضح ورؤيته الشاملة ودعوته للتجديد في مجال الأوقاف.", "keywords": "دور الوقف، يوسف القرضاوي، المجتمع الإسلامي، التنمية، الوقف المعاصر، الوقف النقدي، الصكوك الوقفية"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الأوقاف والسياسة في مصر - إبراهيم البيومي غانم', '9b0f0966b762e089', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 20, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الأوقاف والسياسة في مصر - إبراهيم البيومي غانم", "author": "إبراهيم البيومي غانم", "category": "تاريخي", "year": 1998, "description": "دراسة عن العلاقة بين الأوقاف والسلطة السياسية", "content": "كتاب 'الأوقاف والسياسة في مصر' للدكتور إبراهيم البيومي غانم من الدراسات المهمة التي تتناول العلاقة بين الأوقاف والسلطة السياسية في مصر. نُشر الكتاب عام 1998م.\n\nيتناول الكتاب تاريخ الأوقاف في مصر منذ الفتح الإسلامي حتى نهاية القرن العشرين، مع التركيز على العلاقة بين الأوقاف والدولة. يعرض الكتاب كيف استخدمت الدولة الأوقاف كأداة سياسية، وكيف قاومت الأوقاف محاولات السيطرة عليها.\n\nمن أهم موضوعات الكتاب:\n1. دور الأوقاف في الاستقلال الاقتصادي للمؤسسات الدينية والتعليمية عن الدولة.\n2. محاولات الدولة للسيطرة على الأوقاف عبر التاريخ (الدولة الأيوبية، المملوكية، العثمانية، دولة محمد علي، والدولة الحديثة).\n3. إنشاء وزارة الأوقاف في مصر عام 1913م ودورها في إدارة الأوقاف.\n4. قانون إلغاء الأوقاف الأهلية عام 1952م وآثاره على الأوقاف في مصر.\n5. محاولات إحياء الأوقاف في مصر في العقود الأخيرة.\n\nيحلل الكتاب الأسباب التي دفعت الدولة للسيطرة على الأوقاف، منها: الرغبة في السيطرة على الموارد الاقتصادية، الرغبة في السيطرة على المؤسسات الدينية والتعليمية، ومنع تكوين قوى اقتصادية مستقلة عن الدولة.\n\nيعرض الكتاب آثار سياسات الدولة على الأوقاف، مثل: تراجع دور الأوقاف في المجتمع، ضعف المؤسسات الدينية والتعليمية، وتراجع التكافل الاجتماعي.\n\nيدعو الكتاب إلى إعادة النظر في علاقة الدولة بالأوقاف، بحيث تكون الدولة مشرفة وليست مسيطرة، وبحيث تحتفظ الأوقاف باستقلاليتها الإدارية والمالية.\n\nيُعد الكتاب مرجعاً مهماً لفهم تاريخ الأوقاف في مصر والعالم العربي، والعلاقة بين الأوقاف والسلطة السياسية. يتميز بالتحليل العميق والتوثيق الدقيق.", "keywords": "الأوقاف والسياسة، إبراهيم غانم، مصر، التاريخ، السلطة السياسية، وزارة الأوقاف، الأوقاف الأهلية"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'الوقف ودوره في تنمية المجتمع - عبد العزيز الخياط', '0ab46218387b79c1', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 21, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "الوقف ودوره في تنمية المجتمع - عبد العزيز الخياط", "author": "عبد العزيز الخياط", "category": "إداري", "year": 2006, "description": "دراسة عن دور الوقف في التنمية المستدامة", "content": "كتاب 'الوقف ودوره في تنمية المجتمع' للدكتور عبد العزيز الخياط من الدراسات المهمة التي تتناول دور الوقف في التنمية المستدامة. نُشر الكتاب عام 2006م.\n\nيتناول الكتاب الوقف كأداة للتنمية الشاملة (الاقتصادية والاجتماعية والثقافية)، ويعرض نماذج تطبيقية من الأوقاف الناجحة في البلدان الإسلامية.\n\nمن أهم موضوعات الكتاب:\n1. دور الوقف في التنمية الاقتصادية: توفير رأس المال، خلق فرص العمل، تمويل المشاريع الصغيرة والمتوسطة، والاستثمار في البنية التحتية.\n2. دور الوقف في التنمية الاجتماعية: محاربة الفقر، توفير السكن للمحتاجين، رعاية الأيتام والأرامل، ورعاية ذوي الاحتياجات الخاصة.\n3. دور الوقف في التنمية التعليمية: بناء المدارس والجامعات، توفير المنح الدراسية، دعم البحث العلمي، وتوفير الكتب والمراجع.\n4. دور الوقف في التنمية الصحية: بناء المستشفيات والمراكز الصحية، توفير العلاج المجاني، دعم البحث الطبي، وتوفير الأدوية.\n5. دور الوقف في التنمية الثقافية: بناء المكتبات والمتاحف، دعم الفنون والآداب، حفظ التراث، ونشر الثقافة الإسلامية.\n\nيعرض الكتاب نماذج ناجحة من الأوقاف المعاصرة في مختلف البلدان الإسلامية، مثل:\n- الأوقاف في السعودية: أوقاف الملك عبد العزيز، أوقاف الأمراء، والأوقاف الخيرية.\n- الأوقاف في الكويت: الأمانة العامة للأوقاف ومشاريعها التنموية.\n- الأوقاف في تركيا: مؤسسة الأوقاف التركية ودورها في التنمية.\n- الأوقاف في ماليزيا: أوقاف الولايات ودورها في التعليم والصحة.\n\nيحلل الكتاب عوامل نجاح هذه الأوقاف، مثل: الإدارة الاحترافية، الاستثمار الحكيم، الشفافية، المحاسبة، والابتكار في الصيغ الوقفية.\n\nيقدم الكتاب توصيات عملية لتفعيل دور الوقف في التنمية، منها: نشر ثقافة الوقف، تحديث القوانين والأنظمة، تطوير الإدارة، تنويع الاستثمارات، واستخدام التكنولوجيا.\n\nيُعد الكتاب مرجعاً مفيداً للمسؤولين عن التنمية والأوقاف والباحثين في الاقتصاد الإسلامي.", "keywords": "الوقف والتنمية، عبد العزيز الخياط، التنمية المستدامة، الاقتصاد الإسلامي، الأوقاف المعاصرة"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'صيغ تمويلية مستحدثة للأوقاف - عبد الله بن منصور الغفيلي', '9dafc1072d534a28', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 22, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "صيغ تمويلية مستحدثة للأوقاف - عبد الله بن منصور الغفيلي", "author": "عبد الله بن منصور الغفيلي", "category": "إداري", "year": 2010, "description": "دراسة عن الصيغ التمويلية الحديثة للأوقاف", "content": "كتاب 'صيغ تمويلية مستحدثة للأوقاف' للدكتور عبد الله بن منصور الغفيلي من الدراسات المتخصصة في التمويل الوقفي المعاصر. نُشر الكتاب عام 2010م.\n\nيتناول الكتاب الصيغ التمويلية الحديثة التي يمكن استخدامها في الأوقاف، مع بيان ضوابطها الشرعية وتطبيقاتها العملية. يهدف الكتاب إلى تطوير الأوقاف الإسلامية من خلال استخدام أدوات مالية حديثة متوافقة مع الشريعة.\n\nمن أهم الصيغ التمويلية التي يعرضها الكتاب:\n\n1. الوقف النقدي: وقف الأموال السائلة (نقود، أسهم، سندات إسلامية) واستثمارها في مشاريع مربحة. يعرض الكتاب الخلاف الفقهي حول جواز الوقف النقدي، ويرجح الجواز بضوابط.\n\n2. الصكوك الوقفية: إصدار صكوك (أدوات مالية إسلامية) لجمع التبرعات الوقفية من الجمهور. أنواع الصكوك الوقفية: صكوك المشاركة، صكوك المضاربة، صكوك الإجارة، وصكوك الاستصناع.\n\n3. الوقف بالأسهم: وقف أسهم في شركات مساهمة، بحيث يُصرف ريعها (الأرباح) على الجهة الموقوف عليها.\n\n4. الوقف الاستثماري: إنشاء شركات وقفية تدير مشاريع تجارية وصناعية وعقارية، ويُصرف ريعها على الجهات الخيرية.\n\n5. صناديق الوقف: إنشاء صناديق استثمارية وقفية تجمع أموال الواقفين وتستثمرها بطريقة احترافية.\n\n6. الوقف المؤقت: وقف مؤقت لمدة محددة، ثم يعود إلى الواقف أو ورثته. يعرض الكتاب الخلاف الفقهي حول جوازه.\n\n7. الوقف المشترك: اشتراك عدة أشخاص في وقف واحد، بحيث يملك كل واحد حصة منه.\n\n8. الوقف الإلكتروني: استخدام المنصات الإلكترونية لتسهيل الوقف وإدارته وتوزيع ريعه.\n\nلكل صيغة، يعرض الكتاب: التعريف، الضوابط الشرعية، المزايا، المخاطر، والتطبيقات العملية.\n\nيُعد الكتاب مرجعاً مهماً للمسؤولين عن الأوقاف والمستثمرين والباحثين في التمويل الإسلامي. يتميز بالجمع بين الفقه والاقتصاد والتطبيق.", "keywords": "صيغ تمويلية، الغفيلي، الوقف النقدي، الصكوك الوقفية، الوقف الاستثماري، التمويل الإسلامي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'new_references.json', 'legacy_json_content', 'إدارة وتنمية أموال الوقف - ماجد أبو رخية', 'e4e079ceb3fe1009', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "new_references.json", "row_index": 23, "keys": ["author", "category", "content", "description", "keywords", "title", "year"], "row": {"title": "إدارة وتنمية أموال الوقف - ماجد أبو رخية", "author": "ماجد أبو رخية", "category": "إداري", "year": 2012, "description": "دليل عملي لإدارة واستثمار الأوقاف", "content": "كتاب 'إدارة وتنمية أموال الوقف' للدكتور ماجد أبو رخية من الكتب العملية المتخصصة في إدارة واستثمار الأوقاف. نُشر الكتاب عام 2012م.\n\nيتناول الكتاب الجوانب الإدارية والاستثمارية للأوقاف بطريقة عملية، ويقدم أدوات ونماذج يمكن تطبيقها في إدارة الأوقاف. يستهدف الكتاب المسؤولين عن إدارة الأوقاف والنظار والعاملين في مؤسسات الأوقاف.\n\nمن أهم موضوعات الكتاب:\n\n1. التخطيط الاستراتيجي للأوقاف: تحديد الرؤية والرسالة والأهداف، تحليل البيئة الداخلية والخارجية، وضع الاستراتيجيات، وتحديد مؤشرات الأداء.\n\n2. الهيكل التنظيمي للأوقاف: تصميم الهيكل التنظيمي، تحديد الصلاحيات والمسؤوليات، وإنشاء اللجان المتخصصة.\n\n3. الموارد البشرية في الأوقاف: اختيار العاملين، التدريب والتطوير، تقييم الأداء، والحوافز.\n\n4. الإدارة المالية للأوقاف: إعداد الموازنات، المحاسبة، التدقيق، والتقارير المالية.\n\n5. استثمار أموال الوقف: أنواع الاستثمارات (عقارية، تجارية، صناعية، زراعية، مالية)، معايير اختيار الاستثمارات، إدارة المخاطر، وتقييم الأداء الاستثماري.\n\n6. صيانة أملاك الوقف: التخطيط للصيانة، الصيانة الوقائية، الصيانة التصحيحية، وإدارة المقاولين.\n\n7. تسويق خدمات الوقف: التعريف بالوقف، جذب الواقفين، جذب المستفيدين، والعلاقات العامة.\n\n8. التقنية في إدارة الأوقاف: أنظمة المعلومات الإدارية، قواعد البيانات، المواقع الإلكترونية، والتطبيقات الذكية.\n\n9. الحوكمة في الأوقاف: الشفافية، المساءلة، الإفصاح، الرقابة الداخلية، والرقابة الخارجية.\n\n10. قياس الأداء في الأوقاف: مؤشرات الأداء المالي، مؤشرات الأداء الإداري، مؤشرات الأداء الاجتماعي، وبطاقة الأداء المتوازن.\n\nيقدم الكتاب نماذج عملية ونماذج وثائق يمكن استخدامها في إدارة الأوقاف، مثل: نموذج الخطة الاستراتيجية، نموذج الهيكل التنظيمي، نموذج الموازنة، نموذج التقرير المالي، ونموذج تقييم الأداء.\n\nيُعد الكتاب دليلاً عملياً لا غنى عنه للعاملين في مجال إدارة الأوقاف. يتميز بالتطبيق العملي والأدوات الجاهزة.", "keywords": "إدارة الأوقاف، ماجد أبو رخية، استثمار الأوقاف، التخطيط الاستراتيجي، الحوكمة، قياس الأداء"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/basic_references.json', 'legacy_json_content', 'قانون الأراضي العثماني - المادة 1: تعريف الأراضي', '9c4403d368424a81', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/basic_references.json", "row_index": 1, "keys": ["category", "content", "documentDate", "relevanceKeywords", "source", "tags", "title"], "row": {"title": "قانون الأراضي العثماني - المادة 1: تعريف الأراضي", "content": "المادة الأولى: الأراضي على خمسة أقسام:\n\n1. الأراضي المملوكة (الملك): وهي الأراضي التي يملكها الأفراد ملكية تامة بموجب سند رسمي، ويحق لهم التصرف فيها بالبيع والشراء والهبة والوقف والإرث دون قيد أو شرط.\n\n2. الأراضي الأميرية: وهي الأراضي التي تعود رقبتها للدولة، ويكون للأفراد حق التصرف فيها فقط. لا يجوز بيع رقبة الأرض الأميرية، وإنما يباع حق التصرف فقط.\n\n3. الأراضي الموقوفة: وهي الأراضي التي وقفها أصحابها لجهة خيرية أو ذرية، ولا يجوز بيعها أو التصرف فيها إلا وفق شروط الواقف.\n\n4. الأراضي المتروكة: وهي الأراضي المخصصة للمنفعة العامة كالطرق والساحات والمراعي، ولا يجوز تملكها أو التصرف فيها.\n\n5. الأراضي الموات: وهي الأراضي البور التي لم تُعمّر ولم تُزرع، ويجوز إحياؤها بإذن من الدولة.", "category": "قانوني", "source": "قانون الأراضي العثماني 1858", "tags": "أراضي، ملكية، أميرية، وقف، متروكة، موات", "relevanceKeywords": "تصنيف الأراضي، أنواع الأراضي، ملكية الأرض", "documentDate": "1858-01-01"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/basic_references.json', 'legacy_json_content', 'قانون الأراضي العثماني - المادة 3: الأراضي الأميرية', 'ccc319fc6973de09', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/basic_references.json", "row_index": 2, "keys": ["category", "content", "documentDate", "relevanceKeywords", "source", "tags", "title"], "row": {"title": "قانون الأراضي العثماني - المادة 3: الأراضي الأميرية", "content": "المادة الثالثة: الأراضي الأميرية هي الأراضي التي رقبتها للدولة، وللأفراد حق التصرف فيها فقط.\n\nشروط التصرف في الأراضي الأميرية:\n1. يجب دفع الضرائب المقررة (الميري) سنوياً للدولة\n2. يجب زراعة الأرض وعدم تركها بوراً لمدة تزيد عن ثلاث سنوات\n3. لا يجوز بيع رقبة الأرض، وإنما يباع حق التصرف فقط\n4. يجوز توريث حق التصرف للورثة الشرعيين\n5. يجوز وقف حق التصرف بإذن من الدولة\n\nعقوبة ترك الأرض بوراً:\nإذا ترك صاحب حق التصرف الأرض بوراً لمدة ثلاث سنوات متتالية دون عذر شرعي، يسقط حقه في التصرف، وتعود الأرض للدولة لتمنحها لمن يعمرها.", "category": "قانوني", "source": "قانون الأراضي العثماني 1858", "tags": "أراضي أميرية، حق التصرف، ميري، ضرائب", "relevanceKeywords": "الأراضي الأميرية، حق التصرف، شروط التصرف", "documentDate": "1858-01-01"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/basic_references.json', 'legacy_json_content', 'قانون الأراضي العثماني - المادة 12: وقف الأراضي الأميرية', '44a4357c9a543f1b', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/basic_references.json", "row_index": 3, "keys": ["category", "content", "documentDate", "relevanceKeywords", "source", "tags", "title"], "row": {"title": "قانون الأراضي العثماني - المادة 12: وقف الأراضي الأميرية", "content": "المادة الثانية عشرة: يجوز وقف حق التصرف في الأراضي الأميرية بإذن من السلطان أو من ينوب عنه.\n\nشروط وقف الأراضي الأميرية:\n1. الحصول على إذن رسمي من الدولة (الإرادة السنية)\n2. تسجيل الوقف في السجلات الرسمية\n3. تحديد جهة الوقف (خيري أو ذري)\n4. تعيين ناظر للوقف\n5. استمرار دفع الضرائب المقررة (الميري) من ريع الوقف\n\nأحكام خاصة:\n- إذا لم يُدفع الميري من ريع الوقف، يحق للدولة المطالبة به من ناظر الوقف\n- لا يجوز بيع الأرض الموقوفة إلا في حالات الاستبدال الشرعي\n- يجوز تأجير الأرض الموقوفة بعقد إجارة طويلة (حكر)", "category": "قانوني", "source": "قانون الأراضي العثماني 1858", "tags": "وقف، أراضي أميرية، إرادة سنية، ناظر وقف", "relevanceKeywords": "وقف الأراضي الأميرية، شروط الوقف، الإرادة السنية", "documentDate": "1858-01-01"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/basic_references.json', 'legacy_json_content', 'مجلة الأحكام العدلية - المادة 1: تعريف الوقف', '546949c9ed4ac29f', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/basic_references.json", "row_index": 4, "keys": ["category", "content", "documentDate", "relevanceKeywords", "source", "tags", "title"], "row": {"title": "مجلة الأحكام العدلية - المادة 1: تعريف الوقف", "content": "المادة الأولى: الوقف هو حبس العين عن تمليكها لأحد من العباد، والتصدق بالمنفعة على الفقراء أو على وجه من وجوه الخير.\n\nشرح التعريف:\n- حبس العين: منع بيعها أو هبتها أو توريثها\n- عن تمليكها: لا تصبح ملكاً لأحد بعد الوقف\n- التصدق بالمنفعة: الانتفاع بريع الوقف يكون للجهة الموقوف عليها\n\nأركان الوقف:\n1. الواقف: من يقوم بالوقف\n2. الموقوف: العين التي يتم وقفها\n3. الموقوف عليه: الجهة المستفيدة من الوقف\n4. الصيغة: لفظ الوقف الصريح\n\nشروط الواقف:\n- أن يكون بالغاً عاقلاً\n- أن يكون مالكاً للعين الموقوفة\n- أن يكون مختاراً غير مكره", "category": "فقهي", "source": "مجلة الأحكام العدلية - كتاب الوقف", "tags": "وقف، تعريف، أركان، شروط", "relevanceKeywords": "تعريف الوقف، أركان الوقف، شروط الواقف", "documentDate": "1876-01-01"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/basic_references.json', 'legacy_json_content', 'مجلة الأحكام العدلية - المادة 5: شروط صحة الوقف', '4fdf464c5d754bd4', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/basic_references.json", "row_index": 5, "keys": ["category", "content", "documentDate", "relevanceKeywords", "source", "tags", "title"], "row": {"title": "مجلة الأحكام العدلية - المادة 5: شروط صحة الوقف", "content": "المادة الخامسة: يشترط لصحة الوقف:\n\n1. أن يكون الموقوف مالاً متقوماً: أي له قيمة مالية شرعاً\n2. أن يكون معلوماً: محدداً بالوصف أو المشاهدة\n3. أن يكون مملوكاً للواقف: ملكية تامة صحيحة\n4. أن يكون قابلاً للانتفاع مع بقاء عينه: كالعقار والأثاث\n5. أن يكون الوقف مؤبداً: لا يجوز توقيته بمدة معينة\n6. أن تكون الجهة الموقوف عليها معلومة: محددة بوضوح\n7. أن تكون الجهة الموقوف عليها جهة بر: لا تكون معصية\n\nالأموال التي لا يصح وقفها:\n- المنقولات التي تستهلك بالاستعمال (كالطعام)\n- الأموال المغصوبة أو المسروقة\n- الأموال المجهولة أو غير المحددة", "category": "فقهي", "source": "مجلة الأحكام العدلية - كتاب الوقف", "tags": "شروط الوقف، صحة الوقف، أحكام", "relevanceKeywords": "شروط صحة الوقف، الموقوف، الجهة الموقوف عليها", "documentDate": "1876-01-01"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/basic_references.json', 'legacy_json_content', 'قانون الأوقاف الأردني رقم 23 لسنة 1964 - المادة 1: التعاريف', 'd4e2c9ca99248fe6', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/basic_references.json", "row_index": 6, "keys": ["category", "content", "documentDate", "relevanceKeywords", "source", "tags", "title"], "row": {"title": "قانون الأوقاف الأردني رقم 23 لسنة 1964 - المادة 1: التعاريف", "content": "المادة 1: تعاريف\n\nفي هذا القانون، يكون للكلمات والعبارات التالية المعاني المخصصة لها أدناه ما لم تدل القرينة على خلاف ذلك:\n\nالوزارة: وزارة الأوقاف والشؤون والمقدسات الإسلامية\nالوزير: وزير الأوقاف والشؤون والمقدسات الإسلامية\nالوقف: حبس العين عن تمليكها لأحد من العباد والتصدق بالمنفعة على الفقراء أو على وجه من وجوه الخير\nالوقف الخيري: ما وقف على جهة بر عامة كالفقراء والمساجد والمدارس\nالوقف الذري: ما وقف على الذرية والأولاد\nالناظر: من يتولى إدارة الوقف والإشراف عليه\nالمتولي: من يتولى إدارة الوقف الذري\nالريع: الدخل الناتج عن الوقف", "category": "قانوني", "source": "قانون الأوقاف الأردني رقم 23 لسنة 1964", "tags": "قانون أردني، تعاريف، وقف خيري، وقف ذري", "relevanceKeywords": "قانون الأوقاف الأردني، تعاريف، أنواع الوقف", "documentDate": "1964-01-01"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/basic_references.json', 'legacy_json_content', 'قانون الأوقاف الأردني - المادة 10: إدارة الأوقاف', '31b00dade03d1e70', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/basic_references.json", "row_index": 7, "keys": ["category", "content", "documentDate", "relevanceKeywords", "source", "tags", "title"], "row": {"title": "قانون الأوقاف الأردني - المادة 10: إدارة الأوقاف", "content": "المادة 10: تتولى وزارة الأوقاف إدارة الأوقاف الخيرية والإشراف على الأوقاف الذرية.\n\nصلاحيات الوزارة:\n1. إدارة الأوقاف الخيرية واستثمارها\n2. تعيين النظار والمتولين\n3. الإشراف على صرف ريع الأوقاف\n4. صيانة الأوقاف وعمارتها\n5. استبدال الأوقاف عند الضرورة\n6. رفع الدعاوى القضائية المتعلقة بالأوقاف\n7. قبول الأوقاف الجديدة\n\nواجبات الناظر:\n- المحافظة على الوقف وعمارته\n- استثمار الوقف بالطرق الشرعية\n- صرف الريع على الجهات المستحقة\n- تقديم حساب سنوي للوزارة\n- عدم التصرف في الوقف إلا بإذن من الوزارة", "category": "قانوني", "source": "قانون الأوقاف الأردني رقم 23 لسنة 1964", "tags": "إدارة أوقاف، ناظر، وزارة أوقاف", "relevanceKeywords": "إدارة الأوقاف، صلاحيات الوزارة، واجبات الناظر", "documentDate": "1964-01-01"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قانون الأراضي العثماني - المادة 4: الأراضي الموقوفة', '22abe6c34351d48e', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 1, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قانون الأراضي العثماني - المادة 4: الأراضي الموقوفة", "content": "الأراضي الموقوفة هي الأراضي التي أوقفها أصحابها على جهة بر أو خير. ولا يجوز بيعها أو رهنها أو توريثها، وإنما تبقى على ملك الموقوف عليهم أو الجهة الموقوف عليها.", "category": "قانوني", "source": "قانون الأراضي العثماني (1858)", "tags": "قانون الأراضي، الوقف، الأراضي الموقوفة"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قانون الأراضي العثماني - المادة 36: حقوق المتولي', '65f4fd926418fd4f', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 2, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قانون الأراضي العثماني - المادة 36: حقوق المتولي", "content": "للمتولي على الوقف حق الإدارة والنظر في شؤونه، وله أن يؤجر الأرض الموقوفة بما يحقق مصلحة الوقف، ولا يجوز له التصرف فيها بالبيع أو الرهن.", "category": "قانوني", "source": "قانون الأراضي العثماني (1858)", "tags": "المتولي، إدارة الوقف، حقوق المتولي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'مجلة الأحكام العدلية - المادة 2: أركان الوقف', '05cb4c11858ab00d', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 3, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "مجلة الأحكام العدلية - المادة 2: أركان الوقف", "content": "أركان الوقف أربعة: الواقف، والموقوف، والموقوف عليه، والصيغة. ولا يصح الوقف إلا باجتماع هذه الأركان الأربعة.", "category": "مجلة الأحكام", "source": "مجلة الأحكام العدلية", "tags": "أركان الوقف، الواقف، الموقوف عليه"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'مجلة الأحكام العدلية - المادة 3: شروط الواقف', '3af5f3a9e50a9fb5', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 4, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "مجلة الأحكام العدلية - المادة 3: شروط الواقف", "content": "يشترط في الواقف أن يكون حراً مكلفاً مالكاً للموقوف، فلا يصح وقف العبد ولا الصبي ولا المجنون ولا من لا يملك الموقوف.", "category": "مجلة الأحكام", "source": "مجلة الأحكام العدلية", "tags": "شروط الواقف، الأهلية، الملكية"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'مجلة الأحكام العدلية - المادة 6: استبدال الوقف', 'ec3d524bcbaa3c80', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 5, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "مجلة الأحكام العدلية - المادة 6: استبدال الوقف", "content": "لا يجوز استبدال الوقف إلا إذا تعطلت منافعه بالكلية، أو كان في الاستبدال مصلحة ظاهرة للوقف، وبإذن القاضي.", "category": "مجلة الأحكام", "source": "مجلة الأحكام العدلية", "tags": "استبدال الوقف، المصلحة، القاضي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قانون الأوقاف الأردني - المادة 2: تعريف الوقف الخيري', '64e91eaec67405a2', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 6, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قانون الأوقاف الأردني - المادة 2: تعريف الوقف الخيري", "content": "الوقف الخيري هو ما وقف على جهة بر وخير ابتداءً كالمساجد والمدارس والمستشفيات ودور الأيتام.", "category": "قانوني", "source": "قانون الأوقاف الأردني رقم 23 لسنة 1964", "tags": "الوقف الخيري، جهات البر، المساجد"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قانون الأوقاف الأردني - المادة 3: الوقف الذري', '6939b73c023a7f51', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 7, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قانون الأوقاف الأردني - المادة 3: الوقف الذري", "content": "الوقف الذري هو ما وقف على الذرية ابتداءً ثم على جهة بر وخير انتهاءً.", "category": "قانوني", "source": "قانون الأوقاف الأردني رقم 23 لسنة 1964", "tags": "الوقف الذري، الذرية، الوقف الأهلي"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قانون الأوقاف الأردني - المادة 15: صلاحيات المتولي', 'e67c621531e67e08', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 8, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قانون الأوقاف الأردني - المادة 15: صلاحيات المتولي", "content": "للمتولي إدارة الوقف وتأجير أعيانه واستثمارها بما يحقق مصلحة الوقف، وله أن يقاضي ويقاضى باسم الوقف.", "category": "قانوني", "source": "قانون الأوقاف الأردني رقم 23 لسنة 1964", "tags": "المتولي، الإدارة، التأجير"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قانون الأوقاف الأردني - المادة 20: الإشراف على الأوقاف', '9f5ae55d26b839b2', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 9, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قانون الأوقاف الأردني - المادة 20: الإشراف على الأوقاف", "content": "تشرف وزارة الأوقاف على جميع الأوقاف الخيرية والذرية، ولها حق الرقابة والتفتيش على أعمال المتولين.", "category": "قانوني", "source": "قانون الأوقاف الأردني رقم 23 لسنة 1964", "tags": "وزارة الأوقاف، الإشراف، الرقابة"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قرار بقانون رقم 1 لسنة 2018 - المادة 2: أهداف الوزارة', '8bc2a6e91c0501ab', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 10, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قرار بقانون رقم 1 لسنة 2018 - المادة 2: أهداف الوزارة", "content": "تهدف وزارة الأوقاف والشؤون الدينية إلى إدارة وتنظيم الأوقاف الإسلامية وحمايتها وتنميتها واستثمارها.", "category": "قانوني", "source": "قرار بقانون رقم (1) لسنة 2018 بشأن الأوقاف الإسلامية", "tags": "وزارة الأوقاف، الأهداف، الإدارة"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قرار بقانون 2018 - المادة 5: المجلس الأعلى للأوقاف', 'aff71d32dc9eb8a2', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 11, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قرار بقانون 2018 - المادة 5: المجلس الأعلى للأوقاف", "content": "يشكل مجلس أعلى للأوقاف برئاسة الوزير وعضوية ممثلين عن الجهات ذات العلاقة، ويختص بوضع السياسات العامة للأوقاف.", "category": "قانوني", "source": "قرار بقانون رقم (1) لسنة 2018", "tags": "المجلس الأعلى، السياسات، الوزير"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'قرار بقانون 2018 - المادة 10: حماية الأوقاف', 'b14a26155fb98296', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 12, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "قرار بقانون 2018 - المادة 10: حماية الأوقاف", "content": "تتمتع الأوقاف بالحماية القانونية، ولا يجوز الاعتداء عليها أو الاستيلاء عليها أو تغيير معالمها.", "category": "قانوني", "source": "قرار بقانون رقم (1) لسنة 2018", "tags": "حماية الأوقاف، الاعتداء، الاستيلاء"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'الفقه الحنفي - تعريف الوقف', 'db802c0e3089a313', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 13, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "الفقه الحنفي - تعريف الوقف", "content": "الوقف في الفقه الحنفي هو حبس العين على ملك الواقف والتصدق بالمنفعة. فالعين تبقى على ملك الواقف، والمنفعة تصرف في الجهة الموقوف عليها.", "category": "فقهي", "source": "الفقه الحنفي - كتاب الوقف", "tags": "الفقه الحنفي، تعريف الوقف، حبس العين"}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'scripts/additional_references.json', 'legacy_json_content', 'الفقه الحنفي - شروط صحة الوقف', '59b81f9e0f433dda', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "scripts/additional_references.json", "row_index": 14, "keys": ["category", "content", "source", "tags", "title"], "row": {"title": "الفقه الحنفي - شروط صحة الوقف", "content": "يشترط لصحة الوقف في المذهب الحنفي: التأبيد، والقربة، وخروج الموقوف عن ملك الواقف حكماً، والقبول من الموقوف عليه إن كان معيناً.", "category": "فقهي", "source": "الفقه الحنفي - كتاب الوقف", "tags": "شروط الوقف، التأبيد، القربة"}}$kb07$::jsonb, 'legacy_json_content'),
