  ('knowledge_batch_07', 'research_data/jerusalem_land_references.json', 'legacy_json_content', 'Land registry maps in Palestine during the Ottoman period', '33556d541ad2ed0b', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "research_data/jerusalem_land_references.json", "row_index": 8, "keys": ["author", "category", "keywords", "summary", "title", "type", "url", "year"], "row": {"title": "Land registry maps in Palestine during the Ottoman period", "author": "R Kark, H Gerber", "year": 1984, "category": "law", "type": "بحث أكاديمي", "url": "https://www.tandfonline.com/doi/pdf/10.1179/caj.1984.21.1.30", "summary": "دراسة رائدة منشورة في The Cartographic Journal تتناول خرائط تسجيل الأراضي في فلسطين خلال الفترة العثمانية. تحلل سجلات الأراضي والمجلس الإداري لمنطقة القدس. حصلت على 20 استشهاداً.", "keywords": ["land registry", "Ottoman Palestine", "Jerusalem District", "cartography"]}}$kb07$::jsonb, 'legacy_json_content'),
