  ('knowledge_batch_07', 'knowledge_batch_03_old_db_extracted/old_db_knowledge_register_extracted_sanitized.json', 'legacy_json_content', 'قانون الأراضي العثماني (1858)', '9594c00de73f7b0f', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "knowledge_batch_03_old_db_extracted/old_db_knowledge_register_extracted_sanitized.json", "row_index": 20, "keys": ["author", "authority_tier_candidate", "category", "content_preview", "origin", "origin_file", "registry_key", "source", "supabase_intake_status", "tags", "title", "type", "url", "year"], "row": {"origin": "old_db_success_insert_query", "origin_file": "db-query-1767974719121.json", "title": "قانون الأراضي العثماني (1858)", "category": "law", "source": "الدولة العثمانية", "author": null, "year": null, "type": null, "url": null, "tags": "قانون الأراضي, العثماني, 1858, الطابو, فلسطين", "content_preview": "القانون الأساسي الذي نظم ملكية الأراضي في الدولة العثمانية. قسّم الأراضي إلى خمسة أقسام: المملوكة، الأميرية، الموقوفة، المتروكة، والموات. ما زال ساري النفاذ في الضفة الغربية وغزة. يحتوي على 15 مادة قانونية تفصيلية.\n\nالمصدر: الدولة العثمانية\nالسنة: 1858\nالنوع: قانون", "registry_key": "b2032aa81e4f", "authority_tier_candidate": "official_or_legal_primary_candidate", "supabase_intake_status": "discovered_pending_review_not_applied"}}$kb07$::jsonb, 'legacy_json_content'),
