  ('knowledge_batch_07', 'knowledge_batch_03_old_db_extracted/old_db_knowledge_register_extracted_sanitized.json', 'legacy_json_content', 'أوقاف القدس التاريخية - المسجد الأقصى', '2c3c6c816e7ecca8', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "knowledge_batch_03_old_db_extracted/old_db_knowledge_register_extracted_sanitized.json", "row_index": 87, "keys": ["author", "authority_tier_candidate", "category", "content_preview", "origin", "origin_file", "registry_key", "source", "supabase_intake_status", "tags", "title", "type", "year"], "row": {"origin": "legacy_source_file", "origin_file": "scripts/additional_references.json", "title": "أوقاف القدس التاريخية - المسجد الأقصى", "category": "تاريخي", "source": "دراسات تاريخية عن أوقاف القدس", "author": null, "year": null, "type": null, "tags": "المسجد الأقصى، القدس، الوقف الإسلامي", "content_preview": "المسجد الأقصى المبارك وقف إسلامي خالص منذ الفتح الإسلامي، ولا يجوز التصرف فيه أو في أي جزء منه.", "registry_key": "6e68f93323d2", "authority_tier_candidate": "review_required_candidate", "supabase_intake_status": "discovered_pending_review_not_applied"}}$kb07$::jsonb, 'legacy_json_content'),
