  ('knowledge_batch_07', 'knowledge_batch_04_review_queue/review_queue_import_candidates_v1.json', 'legacy_json_content', 'قرار بقانون رقم (2) لسنة 2023م بشأن تعديل قانون الأوقاف', '78ff1c1345beaf75', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "knowledge_batch_04_review_queue/review_queue_import_candidates_v1.json", "row_index": 28, "keys": ["approval_decision", "author", "authority_tier_candidate", "blocking_flags", "chat_priority", "content_preview", "domain_scope", "human_decision_required", "initial_review_status", "is_chat_eligible", "knowledge_document_status_on_import", "legacy_category", "minimum_checks", "origin", "origin_file", "planned_import_stage", "queue_no", "reference_document_status_on_import", "registry_key", "review_bucket", "reviewer_roles_required", "source", "supabase_dml_status", "target_authority_level_if_approved", "target_category", "target_table_plan", "title", "year"], "row": {"queue_no": 28, "registry_key": "144efe4d0432", "title": "قرار بقانون رقم (2) لسنة 2023م بشأن تعديل قانون الأوقاف", "source": "http://muqtafi.birzeit.edu/pg/getleg.asp?id=18715", "author": "", "year": "", "legacy_category": "إداري", "target_category": "administrative", "domain_scope": "administrative", "authority_tier_candidate": "official_or_legal_primary_candidate", "target_authority_level_if_approved": "official", "review_bucket": "P2_OFFICIAL_REFERENCE_REVIEW", "planned_import_stage": "stage_02_reference_documents_in_review_after_p1", "target_table_plan": "assistant.reference_documents first; assistant.knowledge_documents only after approval/derivation", "reviewer_roles_required": "domain_reviewer;knowledge_admin;senior_knowledge_approver", "minimum_checks": "verify_title_identity;verify_source_identity_or_mark_missing;deduplicate_against_supabase_seed8_and_old_register;assign_reference_document_domain_scope;record_reviewer_and_decision;keep_chat_eligible_false_until_final_approval", "blocking_flags": "", "human_decision_required": "yes", "initial_review_status": "pending_human_approval", "approval_decision": "pending", "reference_document_status_on_import": "in_review", "knowledge_document_status_on_import": "not_created_until_reference_approved", "is_chat_eligible": "false", "chat_priority": "n/a_until_approved", "supabase_dml_status": "not_applied", "origin": "legacy_source_file", "origin_file": "research_data/knowledge_base.json", "content_preview": "قرار بقانون صادر عن السلطة الوطنية الفلسطينية لتعديل قانون الأوقاف والشؤون والمقدسات الإسلامية رقم (26) لسنة 1966م.\n\nالمادة (6) مكرر - المضافة:\n1. تتولى الوزارة جباية الرسوم والأحكار والأعشار الخاصة بالأوقاف الإسلامية\n2. تستوفي الوزارة جميع المستحقات المالية المتعلقة بالأوقاف\n3. تدير الوزارة أموال الأوقاف وفقاً للأحكام الشرعية والقانونية\n\nالهدف: تعزيز صلاحيات وزارة الأوقاف في إدارة الأموال الوقفية وجباية الرسوم."}}$kb07$::jsonb, 'legacy_json_content'),
  ('knowledge_batch_07', 'knowledge_batch_04_review_queue/review_queue_import_candidates_v1.json', 'legacy_json_content', 'نظام الوقف الذري في فلسطين', 'b5905ce301103514', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "knowledge_batch_04_review_queue/review_queue_import_candidates_v1.json", "row_index": 29, "keys": ["approval_decision", "author", "authority_tier_candidate", "blocking_flags", "chat_priority", "content_preview", "domain_scope", "human_decision_required", "initial_review_status", "is_chat_eligible", "knowledge_document_status_on_import", "legacy_category", "minimum_checks", "origin", "origin_file", "planned_import_stage", "queue_no", "reference_document_status_on_import", "registry_key", "review_bucket", "reviewer_roles_required", "source", "supabase_dml_status", "target_authority_level_if_approved", "target_category", "target_table_plan", "title", "year"], "row": {"queue_no": 29, "registry_key": "f1e89b85d36e", "title": "نظام الوقف الذري في فلسطين", "source": "https://www.facebook.com/palestinian.vision/posts/1294708359357491/", "author": "", "year": "", "legacy_category": "إداري", "target_category": "administrative", "domain_scope": "administrative", "authority_tier_candidate": "official_or_legal_primary_candidate", "target_authority_level_if_approved": "official", "review_bucket": "P2_OFFICIAL_REFERENCE_REVIEW", "planned_import_stage": "stage_02_reference_documents_in_review_after_p1", "target_table_plan": "assistant.reference_documents first; assistant.knowledge_documents only after approval/derivation", "reviewer_roles_required": "domain_reviewer;knowledge_admin;senior_knowledge_approver", "minimum_checks": "verify_title_identity;verify_source_identity_or_mark_missing;deduplicate_against_supabase_seed8_and_old_register;assign_reference_document_domain_scope;record_reviewer_and_decision;keep_chat_eligible_false_until_final_approval", "blocking_flags": "", "human_decision_required": "yes", "initial_review_status": "pending_human_approval", "approval_decision": "pending", "reference_document_status_on_import": "in_review", "knowledge_document_status_on_import": "not_created_until_reference_approved", "is_chat_eligible": "false", "chat_priority": "n/a_until_approved", "supabase_dml_status": "not_applied", "origin": "legacy_source_file", "origin_file": "research_data/knowledge_base.json", "content_preview": "الوقف الذري هو نظام شرعي وقانوني يجعل العقار مالاً موقوفاً، ويُكتَب في صكّ الوقف من يحق لهم الاستفادة من ريعه من أبناء المالك وذريته، وبأيّ شروط.\n\nخصائص الوقف الذري:\n1. الاستمرارية: ينتقل من جيل إلى جيل\n2. الحماية: لا يُباع ولا يُورث\n3. التوزيع: يُوزع ريعه على الذرية حسب شرط الواقف\n4. التسجيل: يُسجل في دائرة الأوقاف بصك رسمي\n\nالإحصائيات في القدس:\n- نسبة الوقف الخيري إلى الذري: ما بين (2:1) أو (4:3)\n- عدد الحجج المقدر: لا يقل عن 1200-1600 حجة وقف"}}$kb07$::jsonb, 'legacy_json_content'),
