  ('knowledge_batch_07', 'knowledge_batch_04_review_queue/review_queue_import_candidates_v1.json', 'legacy_json_content', 'قانون العدل والإنصاف للقضاء على مشكلات الأوقاف', 'ab81a884712ea21e', 'assistant', null, 'P1', 'staged', $kb07${"payload_kind": "legacy_json_content_record", "source_file": "knowledge_batch_04_review_queue/review_queue_import_candidates_v1.json", "row_index": 50, "keys": ["approval_decision", "author", "authority_tier_candidate", "blocking_flags", "chat_priority", "content_preview", "domain_scope", "human_decision_required", "initial_review_status", "is_chat_eligible", "knowledge_document_status_on_import", "legacy_category", "minimum_checks", "origin", "origin_file", "planned_import_stage", "queue_no", "reference_document_status_on_import", "registry_key", "review_bucket", "reviewer_roles_required", "source", "supabase_dml_status", "target_authority_level_if_approved", "target_category", "target_table_plan", "title", "year"], "row": {"queue_no": 50, "registry_key": "08a183447918", "title": "قانون العدل والإنصاف للقضاء على مشكلات الأوقاف", "source": "", "author": "محمد قدري باشا", "year": "1893", "legacy_category": "قانوني", "target_category": "law", "domain_scope": "waqf_law", "authority_tier_candidate": "official_or_legal_primary_candidate", "target_authority_level_if_approved": "official", "review_bucket": "P1_LEGAL_PRIMARY_REFERENCE_REVIEW", "planned_import_stage": "stage_01_reference_documents_in_review", "target_table_plan": "assistant.reference_documents first; assistant.knowledge_documents only after approval/derivation", "reviewer_roles_required": "legal_reviewer;senior_knowledge_approver;knowledge_admin", "minimum_checks": "verify_title_identity;verify_source_identity_or_mark_missing;deduplicate_against_supabase_seed8_and_old_register;assign_reference_document_domain_scope;record_reviewer_and_decision;keep_chat_eligible_false_until_final_approval;verify_legal_force;verify_effective_dates;verify_jurisdiction_palestine_or_historical_context;add_article_or_locator_citation;source_missing_blocker", "blocking_flags": "missing_source", "human_decision_required": "yes", "initial_review_status": "pending_human_approval", "approval_decision": "pending", "reference_document_status_on_import": "in_review", "knowledge_document_status_on_import": "not_created_until_reference_approved", "is_chat_eligible": "false", "chat_priority": "n/a_until_approved", "supabase_dml_status": "not_applied", "origin": "legacy_source_file", "origin_file": "new_references.json", "content_preview": "كتاب 'قانون العدل والإنصاف للقضاء على مشكلات الأوقاف' من تأليف محمد قدري باشا (1821-1888م)، وهو أحد أبرز فقهاء القانون في العصر الحديث. يُعد هذا الكتاب من المراجع القانونية المهمة في مجال الأوقاف الإسلامية.\n\nيتناول الكتاب المشكلات القانونية والإدارية التي تواجه الأوقاف الإسلامية، ويقدم حلولاً قانونية مستمدة من الفقه الإسلامي والقانون الوضعي. يعالج الكتاب قضايا مثل: النزاعات على الأوقاف، شروط الواقفين، إدارة الأوقاف، استبدال الأوقاف، والإشراف القضائي على الأوقاف.\n\nألف محمد قدري باشا هذا الكتاب في سياق الإصلاحات القانونية التي شهدتها مصر في القرن التاسع عشر، حيث كان هناك حاجة لتنظيم قانوني حديث"}}$kb07$::jsonb, 'legacy_json_content'),
